export const documentReviewArchitectures = {
  coverage: {
    title: 'Read every section',
    duration: 16600,
    cycle: 3400,
    synthesisAt: 10800,
    steps: [0, 5900, 14400],
  },
  retrieval: {
    title: 'Search for evidence',
    duration: 19200,
    cycle: 4200,
    synthesisAt: 13000,
    steps: [0, 7100, 17000],
  },
};

const coverageRecords = Array.from({ length: 6 }, (_, index) => ({
  label: `Record ${String(index + 1).padStart(2, '0')}`,
  source: Math.floor(index / 2),
  observation: index % 2,
}));
const searchRecords = ['Recorded observation', 'Supporting detail', 'Related evidence'].map((label, source) => ({ label, source, observation: 0 }));
export const clampProgress = (value) => Math.max(0, Math.min(1, value));
export const intervalProgress = (time, start, end) => clampProgress((time - start) / (end - start));
export const smoothProgress = (value) => {
  const p = clampProgress(value);
  return p * p * (3 - 2 * p);
};

// A deterministic timeline keeps pausing, seeking and offscreen resumption continuous.
export function documentReviewFrame(mode, elapsed) {
  const config = documentReviewArchitectures[mode];
  const time = Math.max(0, Math.min(config.duration, elapsed));
  const searching = mode === 'retrieval';
  const round = Math.min(2, Math.floor(time / config.cycle));
  const local = time - round * config.cycle;
  const merging = intervalProgress(time, config.synthesisAt, config.synthesisAt + 2600);
  const finished = time >= config.duration;
  const settling = time >= config.synthesisAt;
  const records = (searching ? searchRecords : coverageRecords).map((record, index) => {
    const start = record.source * config.cycle + (searching ? 2350 : 1150 + record.observation * 1000);
    return { ...record, index, progress: intervalProgress(time, start, start + (searching ? 1100 : 950)) };
  });
  const guidanceIndex = settling ? 2 : local < 800 || local >= 3300 ? 0 : 1;
  let caption;
  if (settling) caption = merging < .65
    ? 'Bring the collected evidence together and apply the decision rules.'
    : 'Synthesise the evidence for each risk, retaining its source references.';
  else if (!searching) caption = local < 1050
    ? 'Read the report page by page, including tables and supporting material.'
    : 'Extract multiple records from each page, keeping their source references.';
  else if (local < 1500) caption = [
    'Use the guidance to search for the facts this risk requires.',
    'Search again for the detail the assessment still needs.',
    'Follow up on related evidence before reaching a conclusion.',
  ][round];
  else if (local < 3300) caption = 'Read the returned passage and retain the relevant evidence.';
  else caption = round < 2
    ? 'Check what evidence is still needed and plan the next search.'
    : 'Check that the required evidence has been collected.';

  return { time, round, local, merging, finished, settling, records, guidanceIndex, caption };
}
