import { buildMuseumPavilion } from './museumPavilionGeometry.js';

// Project the pavilion's real floor plates and walls into the visitor plan.
const pieces = [];
buildMuseumPavilion((width, height, depth, material, x, y, z) => {
  pieces.push({ x:x-width/2, y:z-depth/2, width, height:depth, elevation:y, thickness:height, material, z });
}, { edge:'edge', floor:'floor', stone:'stone', paper:'paper', metal:'metal' });
export const museumPlanFloors = pieces.filter(p => p.thickness < .25 && p.elevation < 0 && p.z > -17);
export const museumPlanWalls = pieces.filter(p => p.thickness > 2 && p.z > -17 && (p.width < .6 || p.height < .6));

